compile.workshop:
variables {
    global:
        0: g
}

rule ("maps") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, First Of(Filtered Array(Array(Map(Colosseo), Map(Esperança), Map(Samoa), Map(Throne of Anubis), Current Map), Compare(Custom String("{0}", Current Map), ==, String Split(Current Array Element, Empty Array)))));
        Set Global Variable(g, Compare(Custom String("{0}", Current Map), ==, Custom String("{0}", Map(Colosseo))));
        Set Global Variable(g, Compare(Current Map, ==, Map(Busan)));
        Set Global Variable(g, Compare(Custom String("{0}", Current Map), ==, Custom String("{0}", Map(Samoa))));
        Set Global Variable(g, Compare(First Of(Filtered Array(Array(Map(Colosseo), Map(Esperança), Map(Samoa), Map(Throne of Anubis), Current Map), Compare(Custom String("{0}", Current Map), ==, String Split(Current Array Element, Empty Array)))), !=, Map(Esperança)));
        Set Global Variable(g, Array(Map(Throne of Anubis), Map(Busan)));
    }
}

